// @pit: {"label": "Analog ensemble: forward 1/3/6-month S&P and Nasdaq returns after closest shape matches"}
async ({ http: { request } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const ts = (d: string) => Math.floor(Date.parse(d) / 1000);
  const chunk = async (sym: string, a: string, z: string) => { const j = JSON.parse((await request(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?period1=${ts(a)}&period2=${ts(z)}&interval=1d`, { maxBytes: 1_000_000, headers: H })).body).chart.result[0]; return j.timestamp.map((t: number, i: number) => [new Date(t * 1000).toISOString().slice(0, 10), j.indicators.quote[0].close[i]] as [string, number]).filter((x: [string, number]) => x[1] != null); };
  const load = async (sym: string, start: number) => { const rs: string[][] = []; for (let y = start; y < 2027; y += 12) rs.push([`${y}-01-01`, y + 12 >= 2027 ? "2026-11-17" : `${y + 12}-01-01`]); const parts = await Promise.all(rs.map(([a, z]) => chunk(sym, a, z))); const seen = new Set<string>(); const S: [string, number][] = []; for (const p of parts) for (const r of p) if (!seen.has(r[0])) { seen.add(r[0]); S.push(r); } return S; };
  const [spx, ixic] = await Promise.all([load("^GSPC", 1950), load("^IXIC", 1971)]);
  const r1 = (x: number) => Math.round(x * 10) / 10;
  const pctl = (a: number[], q: number) => { const s = [...a].sort((x, y) => x - y); const i = (s.length - 1) * q; const lo = Math.floor(i); return s[lo] + (s[Math.ceil(i)] - s[lo]) * (i - lo); };
  const summ = (a: number[]) => ({ n: a.length, p10: r1(pctl(a, 0.1)), p25: r1(pctl(a, 0.25)), med: r1(pctl(a, 0.5)), p75: r1(pctl(a, 0.75)), p90: r1(pctl(a, 0.9)), pctUp: r1((a.filter((x) => x > 0).length / a.length) * 100) });
  const analyze = (S: [string, number][], W: number, cutoff: string) => {
    const d = S.map((x) => x[0]), c = S.map((x) => x[1]), v = c.map(Math.log); const N = v.length; const cur = v.slice(-W);
    let mc = 0; for (const x of cur) mc += x; mc /= W; let sc = 0; for (const x of cur) sc += (x - mc) ** 2;
    const last = d.indexOf(cutoff); const cs: { j: number; c: number }[] = [];
    // rolling sums for speed
    for (let j = W - 1; j <= last; j++) { let mx = 0; for (let i = 0; i < W; i++) mx += v[j - W + 1 + i]; mx /= W; let a = 0, bx = 0; for (let i = 0; i < W; i++) { const p = v[j - W + 1 + i] - mx; a += p * (cur[i] - mc); bx += p * p; } cs.push({ j, c: a / Math.sqrt(bx * sc) }); }
    const sorted = [...cs].sort((a, b) => b.c - a.c); const picks: { j: number; c: number }[] = [];
    for (const s of sorted) { if (picks.length >= 10) break; if (picks.every((p) => Math.abs(p.j - s.j) > 250)) picks.push(s); }
    const fwd = (j: number, h: number) => (c[j + h] != null ? (c[j + h] / c[j] - 1) * 100 : NaN);
    const mdd = (j: number, h: number) => { let m = 0; for (let k = 1; k <= h && j + k < N; k++) m = Math.min(m, c[j + k] / c[j] - 1); return m * 100; };
    const rows = picks.map((p) => ({ end: d[p.j], corr: Math.round(p.c * 1000) / 1000, m1: r1(fwd(p.j, 21)), m3: r1(fwd(p.j, 63)), m6: r1(fwd(p.j, 126)), dd6: r1(mdd(p.j, 126)) }));
    const paths = picks.map((p) => Array.from({ length: 127 }, (_, k) => c[p.j + k] / c[p.j]));
    // unconditional and state-conditional base rates (state: 4-7% below ATH, ATH within last 15-45 sessions)
    let ath = c[0], athAt = 0; const uncond3: number[] = [], uncond6: number[] = [], st1: number[] = [], st3: number[] = [], st6: number[] = [], stdd: number[] = []; let lastState = -999; const stDates: string[] = [];
    for (let j = 0; j < N - 126; j++) { if (c[j] > ath) { ath = c[j]; athAt = j; } uncond3.push(fwd(j, 63)); uncond6.push(fwd(j, 126)); const dd = c[j] / ath - 1; if (dd <= -0.04 && dd >= -0.07 && j - athAt >= 15 && j - athAt <= 45 && j - lastState > 60) { lastState = j; st1.push(fwd(j, 21)); st3.push(fwd(j, 63)); st6.push(fwd(j, 126)); stdd.push(mdd(j, 126)); stDates.push(d[j]); } }
    return { lastDate: d.at(-1), lastClose: r1(c.at(-1)!), rows, ens: { m1: summ(rows.map((r) => r.m1)), m3: summ(rows.map((r) => r.m3)), m6: summ(rows.map((r) => r.m6)), dd6: summ(rows.map((r) => r.dd6)) }, uncond: { m3: summ(uncond3), m6: summ(uncond6) }, state: { m1: summ(st1), m3: summ(st3), m6: summ(st6), dd6: summ(stdd), recent: stDates.slice(-8) }, paths };
  };
  const A = analyze(spx, 1008, "2022-10-31"); const B = analyze(ixic, 1008, "2022-10-31");
  // ensemble fan (percentiles per day) every 3 sessions
  const fan = (paths: number[][], base: number) => { const ks: number[] = []; for (let k = 0; k <= 126; k += 3) ks.push(k); return { ks, p25: ks.map((k) => Math.round(base * pctl(paths.map((p) => p[k]), 0.25))), med: ks.map((k) => Math.round(base * pctl(paths.map((p) => p[k]), 0.5))), p75: ks.map((k) => Math.round(base * pctl(paths.map((p) => p[k]), 0.75))) }; };
  const out = { spx: { ...A, paths: undefined, fan: fan(A.paths, A.lastClose) }, ixic: { ...B, paths: undefined, fan: fan(B.paths, B.lastClose) } };
  return out as unknown as PitJsonValue;
}
